        minv = pv['v'].min()
        maxv = pv['v'].max()
        if maxv > self.maxvalue:
            self.maxvalue = maxv
        if minv < self.minvalue:
            self.minvalue = minv
        return

    @cython.ccall
    def destroy(self) -> bool:
        """Release stored chromosome data and reset caches."""
